"""The shipped image serves the pinned contract, over the wire (plan T3.1, D8, D20).

Needs Docker, needs no Gramps Web: registration happens at import time and the REST client is
lazy, so the handshake and the tool list answer with nothing behind them. That is what makes
this the cheapest possible test of the layer that has twice shipped broken.

`test_00_tool_contract.py` already pins what the *working tree* registers. This file answers
the other half — whether the artifact a client actually spawns says the same thing. The two
cannot substitute for each other: a module missing from the Dockerfile's explicit `COPY` list
leaves the in-process reading perfectly green.

**Only the working-tree leg is compared strictly.** On the released leg (`GRAMPS_E2E_IMAGE_LEG=
released`) a difference means "the artifact is older than this tree", which mid-wave is the
truth and not a defect; the comparison is skipped with the resolved image id named, rather than
weakened into an assertion that would pass for both. The release ritual builds from the tree it
is about to tag, so nothing is lost where it counts.
"""

from __future__ import annotations

from collections.abc import Iterator
from typing import Any

import pytest
from harness import tool_contract
from harness.mcp_container import LEG_WORKING_TREE, ImageRef, McpContainer, container_name

SERVER_NAME = "gramps-remote-mcp"
PROTOCOL_VERSION = "2025-06-18"
GATED_TOOL = "gramps_delete_person"

ENV = {
    "GRAMPS_BASE_URL": "http://gwe2e-nowhere:5000",
    "GRAMPS_USERNAME": "nobody",
    "GRAMPS_PASSWORD": "unused",
}


def spawn(image: ImageRef, runid: str, label: str, env: dict[str, str]) -> McpContainer:
    return McpContainer(
        container_name(runid, label), image.run_reference, env, runid=runid, network="none"
    )


def pages(mcp: McpContainer) -> list[dict[str, Any]]:
    """Every `tools/list` page. The walk itself is proven Docker-free in
    `test_00_tool_contract.py`; this server answers in one page, so proving it here would
    only prove that one page has no successor."""
    return tool_contract.read_pages(mcp.list_tools)


@pytest.fixture(scope="module")
def snapshot() -> dict[str, Any]:
    return tool_contract.load()


@pytest.fixture(scope="module")
def unarmed(mcp_image: ImageRef, e2e_runid: str) -> Iterator[McpContainer]:
    """The default deployment: no destructive flag, which is what a public instance runs."""
    running = spawn(mcp_image, e2e_runid, "proto-off", ENV)
    try:
        yield running
    finally:
        assert running.close() == [], "the MCP container outlived its test"


@pytest.fixture(scope="module")
def armed(mcp_image: ImageRef, e2e_runid: str) -> Iterator[McpContainer]:
    running = spawn(mcp_image, e2e_runid, "proto-on", {**ENV, "GRAMPS_ENABLE_DESTRUCTIVE": "1"})
    try:
        yield running
    finally:
        assert running.close() == [], "the MCP container outlived its test"


def only_the_working_tree(image: ImageRef) -> None:
    if image.leg != LEG_WORKING_TREE:
        pytest.skip(
            f"leg={image.leg} image={image.image_id[:19]}: the committed contract describes "
            "this working tree, so a released artifact may legitimately differ"
        )


def test_the_handshake_names_this_server_and_agrees_on_the_protocol(
    unarmed: McpContainer,
) -> None:
    """If a root module is missing from the image, the server dies here and nowhere else."""
    unarmed.start()
    reply = unarmed.initialize_reply
    assert reply is not None
    result = reply["result"]

    assert result["serverInfo"]["name"] == SERVER_NAME
    assert result["protocolVersion"] == PROTOCOL_VERSION
    assert "tools" in result["capabilities"]


def test_the_shipped_image_serves_the_pinned_contract(
    armed: McpContainer, snapshot: dict[str, Any], mcp_image: ImageRef
) -> None:
    """Descriptions and schemas off the wire, against the snapshot the tree generated.

    This is the assertion that makes a Stage-2 finding attributable: when a real model is
    handed these tools and picks the wrong one, the text it read is on record here.
    """
    only_the_working_tree(mcp_image)

    assert tool_contract.from_wire(pages(armed)) == snapshot["tools"]


def test_the_default_deployment_serves_the_unarmed_contract(
    unarmed: McpContainer, snapshot: dict[str, Any], mcp_image: ImageRef
) -> None:
    """The gate is structural over the wire too: the tools are absent, not refused.

    Compared as entries and not merely as names — a gate that quietly changed a docstring in
    the unarmed build would change what every public deployment shows its model.
    """
    only_the_working_tree(mcp_image)
    served = tool_contract.from_wire(pages(unarmed))

    assert sorted(served) == snapshot["gate_off"]
    assert served == {name: snapshot["tools"][name] for name in snapshot["gate_off"]}


def test_this_server_serves_its_whole_tool_list_in_one_page(armed: McpContainer) -> None:
    """A measurement, pinned: today there is no `nextCursor`, so nobody has to handle one.

    If that ever changes, this is the test that says so — and `read_pages` already follows the
    cursor, so the contract comparison above will keep telling the truth either way.
    """
    collected = pages(armed)

    assert len(collected) == 1
    assert collected[0].get("nextCursor") is None
    assert len(collected[0]["tools"]) == len(tool_contract.load()["tools"])


def test_a_gated_tool_answers_with_a_result_not_a_protocol_error(unarmed: McpContainer) -> None:
    """D20, measured: an unregistered tool is a *successful* call carrying `isError: true`.

    One design section asserted a JSON-RPC `error` object instead. That would have been a
    false red on the only test that proves structural gating over the wire — `McpSession.call`
    raises on an `error` reply, so getting a `ToolResult` at all is half the assertion.
    """
    answer = unarmed.call(GATED_TOOL, {"gramps_id": "I0000", "confirm": True})

    assert answer.is_error is True
    assert answer.text == f"Unknown tool: {GATED_TOOL}"
